    public List<BillingAccount> testGetAll() throws Throwable {
    LOGGER.info( "BillingAccountTest:testGetAll() - Retrieving Collection of BillingAccounts:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all BillingAccount : " );
    List<BillingAccount> collection  = null;

    try {
        // call the static get method on the BillingAccountService
        collection = service.getAllBillingAccount();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            BillingAccount currEntity  = null;
            Iterator<BillingAccount> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getBillingAccountId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

